import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosLabel } from "../../index";
import { KozmosInput } from "../../react-bridge";

/**
 * Vue's Label: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Label`; WithInput drawn by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/Label",
  component: KozmosLabel,
  // React's Label story is centred: the label's box at a fractional x, as
  // React's is, or its baseline is a pixel narrower than React's.
  parameters: { layout: "centered" },
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosLabel, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    children: "Label",
  },
};

/**
 * React's WithInput: a label for an email field. Input is not ported yet,
 * so the field is the bridge's KozmosInput, React's Input mounted in Vue.
 */
export const WithInput: Story = {
  render: () => ({
    components: { KozmosLabel, KozmosInput },
    template: `
      <div style="display: grid; gap: 0.5rem; width: 100%; max-width: 20rem">
        <KozmosLabel for="label-email">Email</KozmosLabel>
        <KozmosInput id="label-email" type="email" placeholder="you@example.com" />
      </div>
    `,
  }),
};
